'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Users, Plus, X, CheckCircle, XCircle, UserPlus } from 'lucide-react';

const ROLE_COLORS: Record<string, string> = {
    super_admin: '#7c3aed',
    admin: '#2563eb',
    hod: '#0891b2',
    faculty: '#059669',
    student: '#d97706',
};

const ROLE_LABELS: Record<string, string> = {
    super_admin: 'Super Admin',
    admin: 'Institution Admin',
    hod: 'Head of Department',
    faculty: 'Faculty',
    student: 'Student',
};

export default function UsersPage() {
    const [users, setUsers] = useState<any[]>([]);
    const [departments, setDepartments] = useState<any[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ email: '', name: '', role: 'student', department_id: '', password: 'edunexis@2026' });
    const [message, setMessage] = useState('');
    const [loading, setLoading] = useState(false);

    useEffect(() => { load(); }, []);

    const load = async () => {
        try {
            const [uRes, dRes] = await Promise.all([
                api.get<any[]>('/api/admin/users'),
                api.get<any[]>('/api/admin/departments').catch(() => ({ success: false, data: [] } as any)),
            ]);
            if (uRes.success) setUsers(uRes.data);
            if (dRes.success) setDepartments(dRes.data);
        } catch { }
    };

    const handleCreate = async () => {
        setLoading(true);
        setMessage('');
        try {
            const res = await api.post<any>('/api/admin/users', {
                email: form.email,
                name: form.name,
                role: form.role,
                department_id: form.department_id || undefined,
                password: form.password,
            });
            if (res.success) {
                setMessage(`✓ User "${form.name}" created. ${res.data.mock_token ? `Login token: ${res.data.mock_token}` : ''}`);
                setShowForm(false);
                setForm({ email: '', name: '', role: 'student', department_id: '', password: 'edunexis@2026' });
                load();
            }
        } catch (err: any) {
            setMessage(`✗ ${err.message || 'Failed to create user'}`);
        }
        setLoading(false);
    };

    const handleToggleActive = async (userId: string, isActive: boolean) => {
        try {
            await api.patch(`/api/admin/users/${userId}`, { is_active: !isActive });
            load();
        } catch { }
    };

    // Group users by role
    const roleOrder = ['admin', 'hod', 'faculty', 'student'];
    const grouped = roleOrder.reduce((acc, role) => {
        acc[role] = users.filter(u => u.role === role);
        return acc;
    }, {} as Record<string, any[]>);

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <div>
                    <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins' }}>
                        User Management
                    </h1>
                    <p style={{ fontSize: 14, color: '#5a6a72' }}>
                        Create and manage institutional users. Only users created here can login.
                    </p>
                </div>
                <button className="btn-primary" onClick={() => setShowForm(true)}>
                    <UserPlus size={16} /> Create User
                </button>
            </div>

            {message && (
                <div style={{
                    padding: '12px 16px', borderRadius: 8, marginBottom: 16,
                    background: message.startsWith('✓') ? '#d1fae5' : '#fee2e2',
                    color: message.startsWith('✓') ? '#065f46' : '#991b1b',
                    fontSize: 14, fontWeight: 500,
                }}>
                    {message}
                </div>
            )}

            {/* Create User Form */}
            {showForm && (
                <div className="card" style={{ marginBottom: 24, padding: 28 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                        <h3 style={{ fontSize: 16, fontWeight: 700, color: '#142B34' }}>
                            <UserPlus size={18} style={{ verticalAlign: 'sub', marginRight: 8 }} />
                            Create New User
                        </h3>
                        <button onClick={() => setShowForm(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
                            <X size={18} color="#8a9aa2" />
                        </button>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                        <div className="form-group">
                            <label>Full Name *</label>
                            <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Dr. Priya Sharma" />
                        </div>
                        <div className="form-group">
                            <label>Email *</label>
                            <input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="priya@institution.edu" />
                        </div>
                        <div className="form-group">
                            <label>Role *</label>
                            <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
                                <option value="admin">Institution Admin</option>
                                <option value="hod">Head of Department</option>
                                <option value="faculty">Faculty</option>
                                <option value="student">Student</option>
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Department</label>
                            <select value={form.department_id} onChange={(e) => setForm({ ...form, department_id: e.target.value })}>
                                <option value="">None</option>
                                {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                            </select>
                        </div>
                        <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                            <label>Default Password</label>
                            <input value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="edunexis@2026" />
                            <p style={{ fontSize: 12, color: '#8a9aa2', marginTop: 4 }}>Used for Firebase mode. Ignored in mock mode.</p>
                        </div>
                    </div>
                    <button className="btn-primary" onClick={handleCreate} disabled={!form.email || !form.name || loading}>
                        {loading ? 'Creating...' : 'Create User'}
                    </button>
                </div>
            )}

            {/* User Stats */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 24 }}>
                {roleOrder.map(role => (
                    <div key={role} className="card" style={{ padding: 20, borderTop: `3px solid ${ROLE_COLORS[role]}` }}>
                        <div style={{ fontSize: 24, fontWeight: 800, color: '#142B34', fontFamily: 'Poppins' }}>
                            {grouped[role]?.length || 0}
                        </div>
                        <div style={{ fontSize: 13, color: '#8a9aa2', fontWeight: 500 }}>
                            {ROLE_LABELS[role]}s
                        </div>
                    </div>
                ))}
            </div>

            {/* User Table */}
            <div className="table-container">
                <table>
                    <thead>
                        <tr>
                            <th>Name</th>
                            <th>Email</th>
                            <th>Role</th>
                            <th>Status</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {users.length === 0 ? (
                            <tr>
                                <td colSpan={5} style={{ textAlign: 'center', padding: 32, color: '#8a9aa2' }}>
                                    <Users size={32} style={{ margin: '0 auto 8px', opacity: 0.3, display: 'block' }} />
                                    No users yet. Click "Create User" to add institutional users.
                                </td>
                            </tr>
                        ) : users.map((u) => (
                            <tr key={u.id} style={{ opacity: u.is_active ? 1 : 0.5 }}>
                                <td style={{ fontWeight: 600 }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                                        <div style={{
                                            width: 32, height: 32, borderRadius: 6,
                                            background: ROLE_COLORS[u.role] || '#666',
                                            color: 'white', display: 'flex', alignItems: 'center',
                                            justifyContent: 'center', fontSize: 13, fontWeight: 700, flexShrink: 0,
                                        }}>
                                            {u.name?.charAt(0)?.toUpperCase() || '?'}
                                        </div>
                                        {u.name}
                                    </div>
                                </td>
                                <td style={{ fontSize: 13, color: '#5a6a72' }}>{u.email}</td>
                                <td>
                                    <span style={{
                                        fontSize: 11, fontWeight: 700, padding: '3px 10px',
                                        borderRadius: 4, background: `${ROLE_COLORS[u.role] || '#666'}15`,
                                        color: ROLE_COLORS[u.role] || '#666', textTransform: 'uppercase',
                                        letterSpacing: 0.5,
                                    }}>
                                        {ROLE_LABELS[u.role] || u.role}
                                    </span>
                                </td>
                                <td>
                                    <span className={`badge ${u.is_active ? 'badge-success' : 'badge-danger'}`}>
                                        {u.is_active ? 'Active' : 'Inactive'}
                                    </span>
                                </td>
                                <td>
                                    <button
                                        onClick={() => handleToggleActive(u.id, u.is_active)}
                                        style={{
                                            padding: '4px 12px', borderRadius: 6, fontSize: 12,
                                            fontWeight: 600, border: 'none', cursor: 'pointer',
                                            background: u.is_active ? '#fee2e2' : '#d1fae5',
                                            color: u.is_active ? '#991b1b' : '#065f46',
                                        }}
                                    >
                                        {u.is_active ? 'Deactivate' : 'Activate'}
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
